package io.tenvyr.executorhost;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.node.ObjectNode;
import io.tenvyr.platform.Json;
import java.io.IOException;
import java.nio.file.*;
import java.util.*;

/** Only startup configuration and immutable database revisions can select executables. */
public record HostConfig(List<Profile> agents,Path allowedRoot,Path stateDir,List<String> callbackOrigins,Map<String,String> callbackKeys,boolean insecure,int port,String bearerTokenEnv,Path launcher,Map<String,String> environment) {
    public record Profile(String agent,String command,List<String> args,Path cwd,Map<String,String> env,Map<String,String> secrets,long wallTimeMs,int maxStdoutBytes,int maxStderrBytes,int port,String bearerTokenEnv,String connectionId,String configHash,String runtimeKind,boolean structuredResult,List<String> modelArgvPrefix,boolean requireExecutionWorkspace) {}
    public record WorkspaceMember(String workspaceExecutionId,String path,String mode,String sourceWorkspaceId,String baseHeadSha) {}
    public static HostConfig fromEnv(){return parse(System.getenv());}
    public static HostConfig parse(Map<String,String> input) {
        Map<String,String> env=new HashMap<>(input);
        Path root=directory(env.getOrDefault("EXECUTOR_HOST_ALLOWED_ROOT",env.getOrDefault("TENVYR_WORKSPACE_ROOT",System.getProperty("java.io.tmpdir"))));
        Path state=Path.of(env.getOrDefault("EXECUTOR_HOST_STATE_DIR",Path.of(System.getProperty("java.io.tmpdir"),"tenvyr-host-state").toString())).toAbsolutePath().normalize();
        try{Files.createDirectories(state);}catch(IOException e){throw invalid("State directory cannot be created");}
        Map<String,String> keys=new LinkedHashMap<>();String rawKeys=env.get("EXECUTOR_HOST_CALLBACK_KEYS");
        if(rawKeys!=null){ObjectNode value=Json.requireObject(Json.parse(rawKeys),"Callback keys");value.fields().forEachRemaining(e->{string(Json.value(e.getKey()),"Callback key",255);keys.put(e.getKey(),string(e.getValue(),"Callback secret",Integer.MAX_VALUE));});}
        else {String http=env.get("HTTP_AGENT_CALLBACK_SECRET"),loop=env.get("LOOPBACK_CALLBACK_SECRET");if(http!=null||loop!=null){keys.put("host-callback-v1",http!=null?http:loop);keys.put("host-loopback-v1",loop!=null?loop:http);}}
        if(keys.isEmpty())throw invalid("Callback authentication keys are required");
        String bearer=env.getOrDefault("EXECUTOR_HOST_BEARER_TOKEN_ENV","EXECUTOR_HOST_BEARER_TOKEN");if(!present(env.get(bearer))&&present(env.get("HTTP_AGENT_BEARER_TOKEN")))env.put(bearer,env.get("HTTP_AGENT_BEARER_TOKEN"));
        int port=positive(Json.value(env.getOrDefault("EXECUTOR_HOST_PORT","3002")),"EXECUTOR_HOST_PORT",65535,true);
        List<Profile> profiles=new ArrayList<>();String raw=env.get("EXECUTOR_HOST_AGENTS");
        if(!present(raw)){if(!present(env.get(bearer)))throw invalid("Bearer token environment value is missing");}
        else {ObjectNode agents=Json.requireObject(Json.parse(raw),"EXECUTOR_HOST_AGENTS");agents.fields().forEachRemaining(e->{String agent=e.getKey();if(agent.length()>255||!agent.matches("[A-Za-z0-9_.-]+")||agent.equals(".")||agent.equals(".."))throw invalid("Invalid agent name");profiles.add(parseProfile(agent,e.getValue(),env,root));});if(profiles.isEmpty())throw invalid("At least one static agent is required");if(profiles.stream().map(Profile::port).distinct().count()!=profiles.size())throw invalid("Every static agent requires a distinct port");}
        List<String> origins=Arrays.stream(env.getOrDefault("EXECUTOR_HOST_CALLBACK_ALLOWED_ORIGINS","http://127.0.0.1:3001,http://localhost:3001,http://127.0.0.1:3000,http://localhost:3000").split(",")).map(String::trim).filter(HostConfig::present).toList();
        Path launcher=Path.of(env.getOrDefault("EXECUTOR_HOST_LAUNCHER","backend/executor-host/native/tenvyr-process-launcher")).toAbsolutePath().normalize();
        if(!Files.isRegularFile(launcher)||!Files.isExecutable(launcher))throw invalid("EXECUTOR_HOST_LAUNCHER must name the built native launcher");
        return new HostConfig(List.copyOf(profiles),root,state,origins,Map.copyOf(keys),"true".equals(env.get("EXECUTOR_HOST_CALLBACK_ALLOW_INSECURE")),port,bearer,launcher,Map.copyOf(env));
    }
    static Profile parseProfile(String agent,JsonNode raw,Map<String,String> env,Path root) {
        ObjectNode value=Json.requireObject(raw,"Agent configuration");String command=string(value.get("command"),"command",4096);Path executable=Path.of(command);if(!executable.isAbsolute()||!Files.isRegularFile(executable)||!Files.isExecutable(executable))throw invalid("Command must be an existing absolute executable");
        List<String> args=args(value.get("args"));String rawCwd=string(value.get("cwd"),"cwd",4096);Path cwd=directory(root.resolve(rawCwd));if(!cwd.startsWith(root))throw invalid("cwd resolves outside allowed root");
        Map<String,String> allow=envMap(value.get("env")),secrets=envMap(value.get("secrets"));String bearer=string(value.get("bearerTokenEnv"),"bearerTokenEnv",255);if(!present(env.get(bearer)))throw invalid("Bearer token environment value is missing");secrets.values().forEach(ref->{if(!present(env.get(ref)))throw invalid("Secret reference environment value is missing");});
        String connection=optional(value,"connectionId",4096),hash=optional(value,"configHash",4096);if((connection==null)!=(hash==null))throw invalid("connectionId and configHash must be declared together");
        return new Profile(agent,command,args,cwd,allow,secrets,positive(value.get("wallTimeMs"),"wallTimeMs",86_400_000,false),positive(value.get("maxStdoutBytes"),"maxStdoutBytes",16*1024*1024,false),positive(value.get("maxStderrBytes"),"maxStderrBytes",16*1024*1024,false),positive(value.get("port"),"port",65535,false),bearer,connection,hash,optional(value,"runtimeKind",255),bool(value,"structuredResult",false),value.has("modelArgvPrefix")?args(value.get("modelArgvPrefix")):null,bool(value,"requireExecutionWorkspace",false));
    }
    public Profile revisionProfile(String agent,JsonNode profile,String connection,String hash) {
        ObjectNode cli=Json.requireObject(profile.get("cli"),"Connection CLI profile");ObjectNode config=Json.object("command",cli.get("command"),"args",cli.has("args")?cli.get("args"):Json.array(),"cwd",cli.hasNonNull("cwd")?cli.get("cwd"):Json.value(allowedRoot.toString()),"env",cli.has("envAllowlist")?cli.get("envAllowlist"):Json.object(),"secrets",cli.has("secrets")?cli.get("secrets"):Json.object(),"wallTimeMs",300000,"maxStdoutBytes",16*1024*1024,"maxStderrBytes",16*1024*1024,"port",port,"bearerTokenEnv",bearerTokenEnv,"connectionId",connection,"configHash",hash,"structuredResult",profile.path("declaredCapabilities").path("structuredResult").path("supported").asBoolean(true),"requireExecutionWorkspace",true);
        if(profile.has("runtimeKind"))config.set("runtimeKind",profile.get("runtimeKind"));if(cli.has("modelArgvPrefix")){JsonNode prefix=cli.get("modelArgvPrefix");config.set("modelArgvPrefix",prefix.isTextual()?Json.array(prefix):prefix);}
        return parseProfile(agent,config,environment,allowedRoot);
    }
    public Map<String,String> resolvedEnvironment(Profile profile){Map<String,String> out=new LinkedHashMap<>();profile.env.forEach((name,ref)->out.put(name,environment.getOrDefault(ref,"")));profile.secrets.forEach((name,ref)->out.put(name,environment.getOrDefault(ref,"")));return out;}
    public static String bindingError(Profile profile,JsonNode invocation){JsonNode carried=invocation.get("connection");if(profile.connectionId!=null){if(carried==null)return "Invocation carries no immutable connection reference";if(!profile.connectionId.equals(Json.text(carried,"connectionId"))||!profile.configHash.equals(Json.text(carried,"configHash")))return "Invocation connection binding does not match the configured profile";}else if(carried!=null)return "Agent declares no connection binding";if(invocation.has("requestedModelId")){JsonNode model=invocation.get("requestedModelId");if(profile.modelArgvPrefix==null||profile.modelArgvPrefix.isEmpty())return "Agent declares no modelArgvPrefix";if(!model.isTextual()||model.asText().length()>256||!model.asText().matches("[A-Za-z0-9][A-Za-z0-9._/\\-:@+]*"))return "Invocation requests an invalid model id";}return null;}
    public static WorkspaceMember workspace(JsonNode invocation){JsonNode metadata=invocation.get("metadata");if(metadata==null||metadata.isNull())return null;Json.requireObject(metadata,"metadata");JsonNode tenvyr=metadata.get("tenvyr");if(tenvyr==null)return null;Json.requireObject(tenvyr,"metadata.tenvyr");JsonNode value=tenvyr.get("executionWorkspace");if(value==null||value.isNull())return null;Json.requireObject(value,"executionWorkspace");Set<String> allowed=Set.of("schemaVersion","workspaceExecutionId","path","mode","sourceWorkspaceId","baseBranch","baseHeadSha");for(String key:Json.keys(value))if(!allowed.contains(key))throw invalid("Unsupported executionWorkspace member");if(!value.path("schemaVersion").isIntegralNumber()||value.path("schemaVersion").asInt()!=1)throw invalid("Unsupported executionWorkspace schemaVersion");String mode=string(value.get("mode"),"mode",255);if(!Set.of("shared","git-worktree").contains(mode))throw invalid("Unsupported executionWorkspace mode");String sha=optional(value,"baseHeadSha",40);if(sha!=null&&!sha.matches("[0-9a-f]{40}"))throw invalid("Invalid executionWorkspace baseHeadSha");optional(value,"baseBranch",255);return new WorkspaceMember(string(value.get("workspaceExecutionId"),"workspaceExecutionId",255),string(value.get("path"),"path",4096),mode,string(value.get("sourceWorkspaceId"),"sourceWorkspaceId",255),sha);}
    public static Path executionCwd(Profile profile,JsonNode invocation,Path root,List<Path> databaseAuthorizedRoots){WorkspaceMember member=workspace(invocation);if(member==null){if(profile.requireExecutionWorkspace)throw invalid("Agent requires an execution workspace");Path cwd=directory(profile.cwd);if(!cwd.startsWith(directory(root)))throw invalid("Static cwd escaped allowed root");return cwd;}Path requested=Path.of(member.path);if(!requested.isAbsolute())throw invalid("Execution workspace path must be absolute");Path real=directory(requested);List<Path> roots=new ArrayList<>();roots.add(root);roots.addAll(databaseAuthorizedRoots);if(roots.stream().map(HostConfig::directory).noneMatch(real::startsWith))throw invalid("Execution workspace resolves outside the authorized roots");return real;}
    static Path directory(Path value){try{Path real=value.toRealPath();if(!Files.isDirectory(real))throw invalid("Path must be an existing directory");return real;}catch(IOException e){throw invalid("Path must be an existing directory");}}
    static Path directory(String value){return directory(Path.of(value));}
    static List<String> args(JsonNode value){if(value==null)return List.of();if(!value.isArray()||value.size()>64)throw invalid("args must contain at most 64 strings");List<String> out=new ArrayList<>();value.forEach(v->out.add(string(v,"arg",1024)));return List.copyOf(out);}
    static Map<String,String> envMap(JsonNode value){if(value==null)return Map.of();Json.requireObject(value,"Environment references");if(value.size()>64)throw invalid("Too many environment references");Map<String,String> out=new LinkedHashMap<>();value.fields().forEachRemaining(e->{if(e.getKey().length()>255||!e.getKey().matches("[A-Za-z0-9_]+"))throw invalid("Invalid environment name");out.put(e.getKey(),string(e.getValue(),"environment reference",255));});return Map.copyOf(out);}
    static String optional(JsonNode value,String key,int max){return !value.hasNonNull(key)?null:string(value.get(key),key,max);}
    static boolean bool(JsonNode value,String key,boolean fallback){if(!value.has(key))return fallback;if(!value.get(key).isBoolean())throw invalid(key+" must be boolean");return value.get(key).asBoolean();}
    static String string(JsonNode value,String field,int max){if(value==null||!value.isTextual()||value.asText().isEmpty()||value.asText().length()>max||value.asText().indexOf('\0')>=0)throw invalid(field+" must be a bounded non-empty string");return value.asText();}
    static int positive(JsonNode value,String field,int max,boolean allowText){long n;try{if(value==null||!value.isIntegralNumber()&&!(allowText&&value.isTextual()&&value.asText().matches("[0-9]+")))throw invalid(field+" must be an integer");n=Long.parseLong(value.asText());}catch(NumberFormatException e){throw invalid(field+" must be an integer");}if(n<=0||n>max)throw invalid(field+" is outside its bounds");return (int)n;}
    static boolean present(String value){return value!=null&&!value.isBlank();}
    static IllegalArgumentException invalid(String message){return new IllegalArgumentException("Invalid Tenvyr local executor host configuration: "+message);}
}
